// Supplied-signature errors observed independently on Salesforce at API67.
func TestRunAuthJWTSignatureErrorProof(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJWTErrorMessages67.cls"), "@IsTest private class GladeJWTErrorMessages67 { @IsTest static void assertsSignatureErrors() { List<Object> results=new List<Object>(); try { Auth.JWT value=Auth.JWTUtil.validateJWTWithKey('eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJvd25lZC1pc3N1ZXIiLCJzdWIiOiJ0YW1wZXJlZC1zdWJqZWN0IiwiYXVkIjoib3duZWQtYXVkaWVuY2UiLCJuYmYiOjAsImV4cCI6NDEwMjQ0NDgwMCwic2NvcGUiOiJvd25lZC1yZWFkIiwicm9sZSI6InJlYWRlciJ9.IB1DoIva1YUmjMlPu7WAs_4yRwNF6MB3iOOUMWXGwa7_vaXqDMrEpKdKy2j3nA2QMracV3LR9Tt9apWIKnT9rHJNNyFJLYAKz-8ZI3MD_hNURpMHm9GQmiakdyh7GWOCP0lfIZweLDtzpSyiZJQARWLvZgcuQNFlZCDfn83TkNFcxIwYR6blpQ-iJ0PFZg0k3YQSRQlnojjTt4Bc7r8MSTL1SQJ3dFTdEOleWf50nTrrY-jlMbrqjdL4a9vv5GBZK8P5BXZ22fbonJ3YiRn0jfANe8KYJS3yaUcaT2X2_DMTmrPQ46xN9Dzg1zj5OGcYnqk012zOMxihwpMQlSqaug',''); results.add(new Map<String,Object>{'case'=>'tamper','returned'=>true}); } catch(Exception error) { results.add(new Map<String,Object>{'case'=>'tamper','type'=>error.getTypeName(),'message'=>error.getMessage()}); } try { Auth.JWT value=Auth.JWTUtil.validateJWTWithKey('eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJvd25lZC1pc3N1ZXIiLCJzdWIiOiJvd25lZC1zdWJqZWN0IiwiYXVkIjoib3duZWQtYXVkaWVuY2UiLCJuYmYiOjAsImV4cCI6NDEwMjQ0NDgwMCwic2NvcGUiOiJvd25lZC1yZWFkIiwicm9sZSI6InJlYWRlciJ9.IB1DoIva1YUmjMlPu7WAs_4yRwNF6MB3iOOUMWXGwa7_vaXqDMrEpKdKy2j3nA2QMracV3LR9Tt9apWIKnT9rHJNNyFJLYAKz-8ZI3MD_hNURpMHm9GQmiakdyh7GWOCP0lfIZweLDtzpSyiZJQARWLvZgcuQNFlZCDfn83TkNFcxIwYR6blpQ-iJ0PFZg0k3YQSRQlnojjTt4Bc7r8MSTL1SQJ3dFTdEOleWf50nTrrY-jlMbrqjdL4a9vv5GBZK8P5BXZ22fbonJ3YiRn0jfANe8KYJS3yaUcaT2X2_DMTmrPQ46xN9Dzg1zj5OGcYnqk012zOMxihwpMQlSqaug',''); results.add(new Map<String,Object>{'case'=>'wrongKey','returned'=>true}); } catch(Exception error) { results.add(new Map<String,Object>{'case'=>'wrongKey','type'=>error.getTypeName(),'message'=>error.getMessage()}); } System.assertEquals(2,results.size()); for(Object raw:results) { Map<String,Object> result=(Map<String,Object>)raw; System.assertEquals('Auth.JWTValidationException',result.get('type')); System.assertEquals('The incomingJWT value isn’t valid. Check the value and try again.',result.get('message')); } } }\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeJWTErrorMessages67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Skipped != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("JWT signature error proof: %s", data)
	}
}
